// === Devpost Hackathons API ===
// Devpost exposes a public JSON listing endpoint that powers their UI.
// Returns ~9-13k hackathons total; we only fetch open ones, capped to 20.
//
// Each result has structured fields, so we skip AI extract entirely
// and construct the Opportunity object inline.

const MONTHS = {
  Jan: 1, Feb: 2, Mar: 3, Apr: 4, May: 5, Jun: 6,
  Jul: 7, Aug: 8, Sep: 9, Oct: 10, Nov: 11, Dec: 12,
};

// "Apr 09 - May 20, 2026" → "2026-05-20". Returns null if unparseable.
function parseDeadline(s) {
  if (!s) return null;
  const m = s.match(/-\s*([A-Za-z]{3,9})\s+(\d{1,2}),?\s*(\d{4})/);
  if (!m) return null;
  const month = MONTHS[m[1].slice(0, 3)];
  if (!month) return null;
  const day = String(m[2]).padStart(2, '0');
  const mm = String(month).padStart(2, '0');
  return `${m[3]}-${mm}-${day}`;
}

let data;
try {
  data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://devpost.com/api/hackathons?status%5B%5D=open&per_page=20',
    json: true,
    headers: { Accept: 'application/json' },
  });
} catch (e) {
  throw new Error('Devpost API fetch failed: ' + ((e && e.message) || e));
}

const hackathons = Array.isArray(data && data.hackathons) ? data.hackathons : [];
if (hackathons.length === 0) {
  throw new Error('Devpost returned 0 hackathons');
}

const out = [];
for (const h of hackathons) {
  const orgName = h.organization_name || 'Devpost';
  const location = (h.displayed_location && h.displayed_location.location) || 'Online';
  const isRemote = location.toLowerCase().includes('online') ||
                   location.toLowerCase().includes('remote') ||
                   location.toLowerCase().includes('worldwide');
  const themes = Array.isArray(h.themes) ? h.themes.map(t => (t && t.name) || '').filter(Boolean) : [];

  const descriptionParts = [];
  if (h.submission_period_dates) descriptionParts.push(`Submission period: ${h.submission_period_dates}`);
  if (h.prize_amount)            descriptionParts.push(`Prize pool: ${h.prize_amount}`);
  if (h.registrations_count)     descriptionParts.push(`${h.registrations_count.toLocaleString()} registered so far`);
  if (themes.length)             descriptionParts.push(`Themes: ${themes.join(', ')}`);
  if (h.invite_only)             descriptionParts.push('Invite-only event');

  const summary = `${orgName} hackathon — ${h.prize_amount || 'prizes available'}, ${h.time_left_to_submission || 'open for submissions'}.`;

  // Build Opportunity object that matches ExtractedOpportunitySchema exactly.
  const opportunity = {
    title: h.title,
    organization: orgName,
    category: 'hackathon',
    description: descriptionParts.join('. ') || null,
    summary: summary.length > 280 ? summary.slice(0, 277) + '...' : summary,
    tags: themes.slice(0, 6).map(t => t.toLowerCase()),
    deadline: parseDeadline(h.submission_period_dates),
    eligibility: h.invite_only ? 'Invite only' : null,
    location: location,
    compensation: h.prize_amount || null,
    is_remote: isRemote,
    apply_url: h.url,
    difficulty: null,
    estimated_value_score: null,
    // High confidence — pre-structured from source, not AI-extracted.
    extraction_confidence: 0.95,
  };

  out.push({ json: { opportunity, source_url: h.url } });
}

return out;
